#include <algorithm>
#include <cstddef>
#include <iostream>
#include <string>
#include <string_view>
#include <unordered_map>
#include <utility>
#include <vector>

// Two route codes are equivalent when one is a rearrangement of the other's letters.
[[nodiscard]] std::vector<std::vector<std::ptrdiff_t>> equivalent_routes(const std::vector<std::string>& codes) {
  std::unordered_map<std::string, std::ptrdiff_t> group_of;  // sorted letters -> that key's position in groups
  std::vector<std::vector<std::ptrdiff_t>> groups;
  for (std::ptrdiff_t i = 0; i < std::ssize(codes); ++i) {
    std::string key = codes[static_cast<std::size_t>(i)];
    std::ranges::sort(key);
    const auto [it, inserted] = group_of.try_emplace(std::move(key), std::ssize(groups));
    if (inserted) {
      groups.push_back({i});
    } else {
      groups[static_cast<std::size_t>(it->second)].push_back(i);
    }
  }
  return groups;
}

void show(std::string_view label, const std::vector<std::vector<std::ptrdiff_t>>& groups) {
  std::cout << label << ':';
  for (const auto& g : groups) {
    std::cout << " {";
    for (std::size_t k = 0; k < g.size(); ++k) {
      if (k) std::cout << ' ';
      std::cout << g[k];
    }
    std::cout << '}';
  }
  std::cout << '\n';
}

int main() {
  show("six codes", equivalent_routes({"abc", "bca", "xyz", "cab", "zzz", "xyz"}));
  show("empty", equivalent_routes({}));
  show("single", equivalent_routes({"a"}));
  show("three of one letter set", equivalent_routes({"aab", "aba", "baa"}));
}

