#include <algorithm>
#include <cstddef>
#include <iostream>
#include <string_view>
#include <utility>
#include <vector>

struct Zones {
  std::vector<std::ptrdiff_t> zone_of;
  std::ptrdiff_t count = 0;
  std::ptrdiff_t largest = 0;
};

// Beacons 0..n-1 and links (undirected, self-loops and repeats allowed); zones numbered 0 upward in
// order of the smallest beacon in each. No recursion, so a long chain cannot overflow the stack.
[[nodiscard]] Zones zone_labels(std::ptrdiff_t n, const std::vector<std::pair<std::ptrdiff_t, std::ptrdiff_t>>& links) {
  std::vector<std::vector<std::ptrdiff_t>> neighbours(static_cast<std::size_t>(n));
  for (const auto& [a, b] : links) {
    if (a == b) continue;  // a self-loop reaches nothing new
    neighbours[static_cast<std::size_t>(a)].push_back(b);
    neighbours[static_cast<std::size_t>(b)].push_back(a);
  }

  Zones zones;
  zones.zone_of.assign(static_cast<std::size_t>(n), -1);
  std::vector<std::ptrdiff_t> stack;
  for (std::ptrdiff_t start = 0; start < n; ++start) {
    if (zones.zone_of[static_cast<std::size_t>(start)] != -1) continue;
    const std::ptrdiff_t zone = zones.count++;
    std::ptrdiff_t size = 0;
    stack.push_back(start);
    zones.zone_of[static_cast<std::size_t>(start)] = zone;
    while (!stack.empty()) {
      const std::ptrdiff_t v = stack.back();
      stack.pop_back();
      ++size;
      for (const std::ptrdiff_t u : neighbours[static_cast<std::size_t>(v)]) {
        if (zones.zone_of[static_cast<std::size_t>(u)] == -1) {
          zones.zone_of[static_cast<std::size_t>(u)] = zone;
          stack.push_back(u);
        }
      }
    }
    zones.largest = std::max(zones.largest, size);
  }
  return zones;
}

void show(std::string_view label, const Zones& zones) {
  std::cout << label << ": zones";
  for (const std::ptrdiff_t z : zones.zone_of) std::cout << ' ' << z;
  std::cout << ", count " << zones.count << ", largest " << zones.largest << '\n';
}

int main() {
  show("mixed", zone_labels(7, {{0, 1}, {1, 2}, {3, 3}, {4, 5}}));
  show("no beacons", zone_labels(0, {}));
  show("one beacon", zone_labels(1, {}));
  show("no links", zone_labels(5, {}));
  show("duplicate links", zone_labels(4, {{0, 1}, {0, 1}, {1, 0}, {2, 3}}));
  show("everyone linked", zone_labels(4, {{0, 1}, {1, 2}, {2, 3}, {3, 0}}));
}

#include <format>
#include <iostream>
#include <memory>
#include <optional>
#include <string>
#include <utility>

struct Node {
  int id = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

[[nodiscard]] std::unique_ptr<Node> node(int id, std::unique_ptr<Node> left = nullptr,
                                         std::unique_ptr<Node> right = nullptr) {
  return std::make_unique<Node>(id, std::move(left), std::move(right));
}

[[nodiscard]] bool holds(const Node* n, int id) {
  if (n == nullptr) return false;
  return n->id == id || holds(n->left.get(), id) || holds(n->right.get(), id);
}

// Reports itself, or whichever of a and b it finds beneath it, up towards the root.
[[nodiscard]] const Node* deepest_shared(const Node* n, int a, int b) {
  if (n == nullptr || n->id == a || n->id == b) return n;
  const Node* left = deepest_shared(n->left.get(), a, b);
  const Node* right = deepest_shared(n->right.get(), a, b);
  if (left != nullptr && right != nullptr) return n;  // a and b are on different sides: this is where they meet
  return left != nullptr ? left : right;
}

[[nodiscard]] std::optional<int> lowest_shared_step(const Node* root, int a, int b) {
  if (!holds(root, a) || !holds(root, b)) return std::nullopt;
  const Node* found = deepest_shared(root, a, b);
  return found != nullptr ? std::optional<int>{found->id} : std::nullopt;
}

[[nodiscard]] std::string text(std::optional<int> value) {
  return value ? std::format("{}", *value) : "none";
}

int main() {
  const auto tree = node(10, node(20, node(40), node(50, node(70), nullptr)), node(30, nullptr, node(60)));
  for (const auto& [a, b] : {std::pair{40, 50}, {40, 70}, {20, 60}, {10, 10}, {20, 30}, {50, 70}, {40, 99}}) {
    std::cout << std::format("({}, {}) -> {}\n", a, b, text(lowest_shared_step(tree.get(), a, b)));
  }
  std::cout << std::format("empty tree -> {}\n", text(lowest_shared_step(nullptr, 1, 2)));
}
